#include <stdbool.h>
#include <stddef.h>

static bool linear_search(const int values[], size_t count, int target, size_t *found)
{
    if (found == NULL || (count > 0U && values == NULL)) {
        return false;
    }
    for (size_t i = 0; i < count; ++i) {
        if (values[i] == target) {
            *found = i;
            return true;
        }
    }
    return false;
}

int main(void)
{
    const int data[] = {7, 2, 9, 2};
    size_t position = 0U;
    return linear_search(data, 4U, 9, &position) && position == 2U ? 0 : 1;
}

#include <stdbool.h>
#include <stddef.h>

static bool binary_search_first(const int values[], size_t count, int target, size_t *found)
{
    if (found == NULL || (count > 0U && values == NULL)) return false;
    size_t low = 0U, high = count;
    while (low < high) {
        size_t mid = low + (high - low) / 2U;
        if (values[mid] < target) low = mid + 1U;
        else high = mid;
    }
    if (low < count && values[low] == target) {
        *found = low;
        return true;
    }
    return false;
}

int main(void)
{
    const int sorted[] = {1, 3, 3, 3, 8, 10};
    size_t position = 0U;
    return binary_search_first(sorted, 6U, 3, &position) && position == 1U ? 0 : 1;
}
